// Bounded particle storage: reused slots, no per-particle object allocation.
export class ParticlePool{
 constructor(capacity=256){this.capacity=capacity;this.cursor=0;this.count=0;this.data=new Float32Array(capacity*9);this.colors=new Array(capacity);}
 burst(x,y,color,count=18,power=1){for(let n=0;n<count;n++){const slot=this.cursor++%this.capacity,i=slot*9,a=n/count*Math.PI*2+Math.random()*.5,speed=(12+Math.random()*35)*power;this.data.set([x,y,Math.cos(a)*speed,Math.sin(a)*speed-14,0,.35+Math.random()*.45,1+Math.random()*2.5,0,0],i);this.colors[slot]=color;}this.count=Math.min(this.capacity,this.count+count);}
 update(dt){for(let n=0;n<this.capacity;n++){const i=n*9;if(this.data[i+5]<=0)continue;this.data[i+4]+=dt;this.data[i+5]-=dt;this.data[i]+=this.data[i+2]*dt;this.data[i+1]+=this.data[i+3]*dt;this.data[i+3]+=30*dt;}}
 draw(g,economy=false){g.save();g.globalCompositeOperation='lighter';for(let n=0;n<this.capacity;n+=(economy?2:1)){const i=n*9,left=this.data[i+5];if(left<=0)continue;g.globalAlpha=Math.min(1,left*3);g.fillStyle=this.colors[n];const x=this.data[i],y=this.data[i+1],size=this.data[i+6];g.fillRect(x,y,size,size);g.globalAlpha*=.15;g.fillRect(x-2,y-2,size+4,size+4);}g.restore();}
}
export function drawBladeTrail(g,x,y,angle,progress,color='#ffc45e',scale=1){g.save();g.translate(x,y);g.rotate(angle);g.scale(scale,scale*.56);g.globalCompositeOperation='lighter';const a=-2.6+progress*2.4;for(let layer=0;layer<4;layer++){g.beginPath();g.arc(0,0,37+layer*4,a-.8,a+.8);g.lineWidth=12-layer*2.5;g.strokeStyle=layer===3?'#fff7dc':color;g.globalAlpha=(1-progress)*(.08+layer*.12);g.stroke();}g.restore();}
export function drawGreatsword(g,t,attack,enchant=0,hasWeapon=true,facingLeft=false,progress=0,moving=false,texture=null,tier=2){if(!hasWeapon)return;g.save();if(facingLeft)g.scale(-1,1);const hands=[[35,-55],[-6,-104],[43,-58],[24,-45]],hand=hands[Math.min(3,Math.floor(progress*4))];g.translate(attack?hand[0]:moving?22:29,attack?hand[1]:moving?-48:-42);g.rotate(attack?-1.1+progress*2.5:.36);if(texture){const cw=texture.naturalWidth/2,ch=texture.naturalHeight/2;g.drawImage(texture,(tier%2)*cw,Math.floor(tier/2)*ch,cw,ch,-18,-85,36,100);}else{const metal=g.createLinearGradient(-5,0,6,0);metal.addColorStop(0,'#17202d');metal.addColorStop(.27,'#768da1');metal.addColorStop(.48,'#f3f0da');metal.addColorStop(.6,'#8099ad');metal.addColorStop(1,'#243044');g.fillStyle=metal;g.strokeStyle='#152435';g.lineWidth=.7;g.beginPath();g.moveTo(-4,0);g.lineTo(-4,-57);g.lineTo(1,-68);g.lineTo(6,-57);g.lineTo(4,0);g.closePath();g.fill();g.stroke();g.fillStyle='#b18c4a';g.fillRect(-9,-1,18,3);g.fillStyle='#292128';g.fillRect(-2,2,4,10);}if(enchant>0){const color=enchant>=20?'#67f8ff':enchant>=10?'#8ac6ff':'#ffd37a';g.globalCompositeOperation='lighter';g.strokeStyle=color;g.lineWidth=1.2;g.beginPath();g.moveTo(1,-62);g.lineTo(1,-5);g.stroke();g.globalAlpha=.22;g.lineWidth=5;g.stroke();for(let n=0;n<Math.min(8,Math.ceil(enchant/3));n++){g.globalAlpha=.6;g.fillStyle=n%2?'#fff':color;g.fillRect(Math.sin(t*3+n*2)*5,-((t*23+n*12)%62),1.2,2);}}g.restore();}
